<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoGrado, guardarGrado, listarGrados } from '../services/gradosInstruccion'
import type { GradoInstruccion, GradoPayload } from '../interfaces/gradosInstruccion.interface'
const rows=ref<GradoInstruccion[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<GradoPayload>({codigo:'',descripcion:'',orden_nivel:null})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarGrados(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(value){error.value=message(value)}finally{loading.value=false}}
function open(item?:GradoInstruccion){editing.value=item?.id??null;Object.assign(form,{codigo:item?.codigo??'',descripcion:item?.descripcion??'',orden_nivel:item?.orden_nivel??null});error.value='';modal.value=true}
async function save(){const codigo=form.codigo.trim().toUpperCase(),descripcion=form.descripcion.trim().toUpperCase();if(!codigo)return void(error.value='El código es obligatorio.');if(codigo.length>10)return void(error.value='El código admite como máximo 10 caracteres.');if(descripcion.length<3)return void(error.value='La descripción debe tener al menos 3 caracteres.');if(form.orden_nivel!==null&&(form.orden_nivel<1||form.orden_nivel>999))return void(error.value='El orden de nivel debe estar entre 1 y 999.');saving.value=true;error.value='';try{await guardarGrado(editing.value,{codigo,descripcion,orden_nivel:form.orden_nivel||null});modal.value=false;success.value=`Grado de instrucción ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:GradoInstruccion){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el grado ${item.descripcion}?`))return;error.value='';try{const r=await cambiarEstadoGrado(item.id);item.estado=r.estado;success.value=r.message??`Grado de instrucción ${item.estado?'activado':'desactivado'} correctamente.`}catch(value){error.value=message(value)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Grados de instrucción</nav><header class="hero"><div class="mark">GI</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Grados de instrucción</h1><p>Niveles educativos ordenados para la formación académica de los trabajadores.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo grado</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por código o descripción<input v-model.trim="criterio" placeholder="Ej. UNI o UNIVERSITARIO"></label><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><header><div><small>MAESTRO DE PERSONAL</small><h2>Grados registrados</h2></div></header><div v-if="loading" class="empty">Consultando grados…</div><div v-else-if="!rows.length" class="empty">No se encontraron grados de instrucción.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Código</th><th>Descripción</th><th>Orden</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td><span class="order">{{item.orden_nivel??'—'}}</span></td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">GI</div><div><small>MAESTRO DE PERSONAL</small><h2>{{editing?'Editar':'Registrar'}} grado</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Descripción *<input v-model="form.descripcion" maxlength="150" @input="form.descripcion=form.descripcion.toUpperCase()"></label><label>Orden de nivel<input v-model.number="form.orden_nivel" type="number" min="1" max="999" placeholder="Opcional"><small>Valor entre 1 y 999.</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fff0f5;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(440px,100%);font-size:.52rem}.filters input,.dialog input{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.54rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive,.order{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.order{color:#35647d;background:#e8f4fa}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(680px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:10px;font-size:.5rem}.dialog label small{margin-top:3px;color:#89959a}.grid{display:grid;grid-template-columns:1fr 2fr 1fr;gap:9px}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
